/*
 * VTOCE_$LOOKUP_FM - Find (or make) the file-map block of a segment
 *
 * Original address: 0x00E39A04 (SAU2 map: VTOCE_$LOOKUP_FM)
 * Size: 446 bytes (0x00E39A04 .. 0x00E39BC1), with its nested procedure
 * vtoc_$fm_traverse at 0x00E397D0 .. 0x00E39A03 (564 bytes, no map
 * symbol; static link in A1).
 * Generated by: Claude Opus 5.5
 *
 * Every segment of a file has a 32-entry file map.  The maps of segments
 * 1..8 hang off the VTOCE's direct root, 9..0x808 off its single-indirect
 * root and the rest off its double-indirect root (8 maps per 1 KB block,
 * 256 blocks per indirect block).  Segment 0's map sits in the VTOCE
 * itself.  The result is the map's location, block << 4 | slot, merged into
 * *fm_loc.  With `allocate' true, missing indirect and map blocks are
 * allocated (BAT_$ALLOC_FM or BAT_$ALLOCATE near a neighbour), zeroed, and
 * counted in *alloc_count.
 *
 * Frame (link.w A6,-0x20; D2-D3/A2-A5 saved; A5 = 0xE784D0, vtoc_$data):
 *   (0x08,A6) loc: the object's location record (+0x04 VTOCE block << 4 |
 *             entry, +0x08 uid, +0x1C volume index)
 *   (0x0C,A6) segment word (D2)   (0x0E,A6) allocate, a BOOLEAN byte read
 *             only by the nested procedure (`tst.b (0xe,A2)` 0x00E397FC)
 *   (0x10,A6) fm_loc (A2)   (0x14,A6) alloc_count   (0x18,A6) status
 *   (-0x0C) SET_BUFF status, (-0x10) the logical block the next map level
 *   starts at, (-0x14) current block, (-0x16) volume, (-0x18) SET_BUFF
 *   flags, (-0x1A) maps per entry at the next level, (-0x1C) index
 *
 * Blocks:
 *   0x00E39A12-0x00E39A4C  unpack loc; ML_$LOCK(0x10)
 *   0x00E39A4E-0x00E39A94  not mounted: "VTOC not mounted"; else read the
 *                          VTOCE block (DBUF_$GET_BLOCK, VTOC_$UID); a
 *                          failure unlocks
 *   0x00E39A96-0x00E39AAA  segment 0: the map is the VTOCE entry itself
 *   0x00E39AAE-0x00E39B4E  the entry's roots (+0xCC of a 0x150-byte new
 *                          format entry, +0xC4 of a 0xCC-byte old one);
 *                          walk the direct (level 1), indirect (2) or
 *                          double-indirect (3) root
 *   0x00E39B52-0x00E39BAC  DBUF_$SET_BUFF the VTOCE block; its status
 *                          stands only if none was set; a read-only volume
 *                          gives block 1, slot 0xF, status 0; merge the
 *                          location into *fm_loc
 *   0x00E39BAC-0x00E39BB2  ML_$UNLOCK(0x10)
 *
 * Quirks reproduced:
 *   - *fm_loc keeps its own low four bits under the block number, then the
 *     slot's whole low byte is ORed into byte 3 after clearing only its low
 *     nibble (0x00E39B90-0x00E39BA8).
 *   - The nested procedure zeroes a freshly got block before looking at
 *     the status DBUF_$GET_BLOCK returned (0x00E398D8-0x00E398EC).
 *   - Its result is its flags as they stood before the child's were ORed
 *     in, less bit 1 (0x00E398F8, returned from (-0x16,A6) at 0x00E399F6).
 */

#include "vtoc/vtoc_internal.h"

/* ML_$LOCK / ML_$UNLOCK id, `move.w #0x10,-(SP)` */
#define VTOC_FM_LOCK            0x10

/* Where an entry's file-map roots start (0x00E39AC6 / 0x00E39AD6) */
#define VTOC_FM_NEW_ENTRY_SIZE  0x150
#define VTOC_FM_NEW_ROOTS       0xCC
#define VTOC_FM_OLD_ENTRY_SIZE  0xCC
#define VTOC_FM_OLD_ROOTS       0xC4

/* Segment ranges of the three roots and their starting logical blocks */
#define VTOC_FM_DIRECT_LIMIT    9       /* cmpi.w #0x9 */
#define VTOC_FM_INDIRECT_LIMIT  0x809   /* cmpi.w #0x809 */

/* DBUF_$SET_BUFF flags: 8 = release, 0xB = written; bit 1 is dropped from
 * the nested procedure's result (`moveq #-0x3; and.w D5w`) */
#define VTOC_FM_BUF_CLEAN       0x08
#define VTOC_FM_BUF_NEW         0x0B
#define VTOC_FM_RESULT_MASK     0xFFFD

/* DBUF_$GET_BLOCK flags for a block about to be initialised (0x00E398BE) */
#define VTOC_FM_GET_NEW         0x10

/* A read-only volume's substitute location (0x00E39B7E-0x00E39B84) */
#define VTOC_FM_RO_BLOCK        1
#define VTOC_FM_RO_SLOT         0x0F

/*
 * The enclosing-scope cells vtoc_$fm_traverse reaches through its static
 * link (A1 -> A2, the caller's A6).  A C flattening of the Pascal frame,
 * not an image record, so it carries no layout asserts.
 */
typedef struct vtoce_$lookup_fm_frame_t {
    vtoc_$lookup_req_t *loc;            /* (0x08,A2) */
    int8_t             allocate;        /* (0x0E,A2) */
    uint32_t           *alloc_count;    /* (0x14,A2) */
    status_$t          *status;         /* (0x18,A2) */
    status_$t          set_status;      /* (-0x0C,A2) */
    uint32_t           base;            /* (-0x10,A2) */
    uint32_t           block;           /* (-0x14,A2) */
    uint16_t           vol;             /* (-0x16,A2) */
    uint16_t           divisor;         /* (-0x1A,A2) */
    uint16_t           index;           /* (-0x1C,A2) */
} vtoce_$lookup_fm_frame_t;

/*
 * vtoc_$fm_traverse - one level of the walk (0x00E397D0 .. 0x00E39A03)
 *
 * Frame (link.w A6,-0x18; D2-D7/A2-A3 saved; A5 the caller's):
 *   (0x08,A6) block_ptr (D3): the root or indirect entry naming this level
 *   (0x0C,A6) level word (D4): 1 = block_ptr names the map block
 *   (0x0E,A6) hint long (D2): where to allocate near
 *   (-0x16,A6) result;  D5w SET_BUFF flags;  A3 this level's buffer
 *
 *   0x00E397E4-0x00E397F8  a block is there: it is current, no buffer
 *   0x00E397FC-0x00E3989C  none: not allocating -> "no file map"; a
 *                          read-only volume -> 0xF0016; else allocate
 *                          (new format: BAT_$ALLOC_FM without a hint,
 *                          BAT_$ALLOCATE near it with one; old format:
 *                          BAT_$ALLOCATE near the current block unless that
 *                          is the VTOCE's own, then anywhere)
 *   0x00E398A0-0x00E398F6  count it, get it zeroed, store it; flags 0xB
 *   0x00E398F8-0x00E3993E  result = flags & ~2; above level 1 read the
 *                          block if not yet held
 *   0x00E39942-0x00E399B4  pick the entry for the index, narrow the index
 *                          and the starting block; an empty entry's hint
 *                          is this block (entry 0), 0 (above level 2 or an
 *                          entry at a multiple of 8), else the nearest
 *                          non-zero entry before it in its group of 8
 *   0x00E399B6-0x00E399F0  recurse; release the buffer with the combined
 *                          flags (a failure's SET_BUFF status goes to the
 *                          scratch cell)
 */
static uint16_t vtoc_$fm_traverse(vtoce_$lookup_fm_frame_t *up,
                                  uint32_t *block_ptr, int16_t level,
                                  uint32_t hint)
{
    uint16_t result;                    /* (-0x16,A6) */
    uint16_t flags;                     /* D5w */
    uint32_t *buf;                      /* A3 */
    uint16_t slot;                      /* D3w */
    uint16_t back;                      /* D1w */
    uint16_t k;                         /* D2w */

    /* 0x00E397E4-0x00E397F8 */
    flags = VTOC_FM_BUF_CLEAN;
    result = flags;
    if (*block_ptr != 0) {
        up->block = *block_ptr;
        buf = NULL;
        goto have_block;
    }

    /* 0x00E397FC-0x00E3982A */
    if (up->allocate >= 0) {
        *up->status = status_$VTOC_no_file_map;
        return result;
    }
    if (vtoc_$data.cach_wp_flag[up->vol - 1] < 0) {        /* (0x26f,A5,vol) */
        *up->status = status_$file_volume_has_been_mounted_read_only;
        return result;
    }

    /* 0x00E3982C-0x00E3989C */
    if (vtoc_$data.format[up->vol] < 0) {
        if (hint == 0) {
            up->block = BAT_$ALLOC_FM((int16_t)up->vol, up->status);
        } else {
            BAT_$ALLOCATE((int16_t)up->vol, hint, 1, 0, &up->block, up->status);
        }
    } else {
        if ((up->loc->block_hint >> 4) == up->block) {
            up->block = 0;
        }
        BAT_$ALLOCATE((int16_t)up->vol, up->block, 1, 0, &up->block, up->status);
    }

    /* 0x00E398A0-0x00E398F6 */
    if (*up->status != status_$ok) {
        return result;
    }
    (*up->alloc_count)++;
    buf = (uint32_t *)DBUF_$GET_BLOCK(up->vol, (int32_t)up->block,
                                      &up->loc->uid, up->base,
                                      (uint16_t)level, VTOC_FM_GET_NEW,
                                      up->status);
    for (k = 0; k <= 0xFF; k++) {                           /* #0xff / dbf */
        buf[k] = 0;
    }
    *block_ptr = up->block;
    flags = VTOC_FM_BUF_NEW;

have_block:
    /* 0x00E398F8-0x00E3993E */
    result = flags & VTOC_FM_RESULT_MASK;
    if (level > 1) {
        if (buf == NULL) {
            buf = (uint32_t *)DBUF_$GET_BLOCK(up->vol, (int32_t)up->block,
                                              &up->loc->uid, up->base,
                                              (uint16_t)level, 0, up->status);
            if (*up->status != status_$ok) {
                return result;
            }
        }

        /* 0x00E39942-0x00E39968 */
        slot = up->index / up->divisor;                     /* divu.w */
        up->index &= (uint16_t)(up->divisor - 1);
        up->base += ((uint32_t)slot * up->divisor) << 5;
        up->divisor = 8;

        /* 0x00E3996A-0x00E399B4 */
        if (buf[slot] == 0) {
            if (slot == 0) {
                hint = up->block;
            } else if (level > 2 || (slot & 7) == 0) {
                hint = 0;
            } else {
                k = (uint16_t)(slot - 1);
                back = (uint16_t)(slot & 0xFFF8);
                if (k >= back) {                            /* bcs skips */
                    back = (uint16_t)(k - back);
                    hint = (hint & 0xFFFF0000u) | k;        /* move.w D0w,D2w */
                    for (;;) {
                        hint = buf[k];
                        if (hint != 0) {
                            break;
                        }
                        k--;
                        if (back-- == 0) {                  /* dbf D1w */
                            break;
                        }
                    }
                }
            }
        }

        /* 0x00E399B6-0x00E399EC */
        flags |= vtoc_$fm_traverse(up, &buf[slot], (int16_t)(level - 1), hint);
        if (*up->status != status_$ok) {
            DBUF_$SET_BUFF(buf, flags, &up->set_status);
            return result;
        }
    }

    /* 0x00E399E0-0x00E399F0 */
    if (buf != NULL) {
        DBUF_$SET_BUFF(buf, flags, up->status);
    }
    return result;
}

void VTOCE_$LOOKUP_FM(void *vtoce_loc, uint16_t segment, int8_t allocate,
                      uint32_t *fm_loc, uint32_t *alloc_count,
                      status_$t *status)
{
    vtoce_$lookup_fm_frame_t f;
    uint16_t entry;                     /* D3w */
    uint16_t set_flags;                 /* (-0x18,A6) */
    uint8_t *vtoce_buf;                 /* A3 */
    uint32_t *roots;                    /* A4 */

    /* 0x00E39A12-0x00E39A4C */
    f.loc = (vtoc_$lookup_req_t *)vtoce_loc;
    f.allocate = allocate;
    f.alloc_count = alloc_count;
    f.status = status;
    f.block = f.loc->block_hint >> 4;
    entry = (uint16_t)(f.loc->block_hint & 0x0F);         /* byte +7 & 0xF */
    f.vol = f.loc->vol_idx;
    ML_$LOCK(VTOC_FM_LOCK);

    /* 0x00E39A4E-0x00E39A94 */
    if (vtoc_$data.mounted[f.vol] >= 0) {
        *status = status_$VTOC_not_mounted;
        vtoce_buf = NULL;
    } else {
        vtoce_buf = (uint8_t *)DBUF_$GET_BLOCK(f.vol, (int32_t)f.block,
                                               &VTOC_$UID, f.block, 0, 0,
                                               status);
    }
    if (*status != status_$ok) {
        goto unlock;
    }

    /* 0x00E39A96-0x00E39AAA */
    set_flags = VTOC_FM_BUF_CLEAN;
    *alloc_count = 0;
    if (segment == 0) {
        f.index = entry;
    } else {
        /* 0x00E39AAE-0x00E39AD6 */
        if (vtoc_$data.format[f.vol] < 0) {
            roots = (uint32_t *)(void *)(vtoce_buf +
                                         (uint32_t)entry * VTOC_FM_NEW_ENTRY_SIZE +
                                         VTOC_FM_NEW_ROOTS);
        } else {
            roots = (uint32_t *)(void *)(vtoce_buf +
                                         (uint32_t)entry * VTOC_FM_OLD_ENTRY_SIZE +
                                         VTOC_FM_OLD_ROOTS);
        }

        /* 0x00E39ADA-0x00E39B4E */
        if (segment < VTOC_FM_DIRECT_LIMIT) {
            f.index = (uint16_t)(segment - 1);
            f.base = 0x20;
            set_flags = vtoc_$fm_traverse(&f, &roots[0], 1, 0);
        } else if (segment < VTOC_FM_INDIRECT_LIMIT) {
            f.index = (uint16_t)(segment - VTOC_FM_DIRECT_LIMIT);
            f.base = 0x120;
            f.divisor = 8;
            set_flags = vtoc_$fm_traverse(&f, &roots[1], 2, 0);
        } else {
            f.index = (uint16_t)(segment - VTOC_FM_INDIRECT_LIMIT);
            f.base = 0x10120;
            f.divisor = 0x800;
            set_flags = vtoc_$fm_traverse(&f, &roots[2], 3, 0);
        }
    }

    /* 0x00E39B52-0x00E39B8E */
    DBUF_$SET_BUFF(vtoce_buf, set_flags, &f.set_status);
    if (*status == status_$ok) {
        *status = f.set_status;
    } else if (*status == status_$file_volume_has_been_mounted_read_only) {
        f.block = VTOC_FM_RO_BLOCK;
        f.index = VTOC_FM_RO_SLOT;
        *status = status_$ok;
    }

    /* 0x00E39B90-0x00E39BA8 */
    *fm_loc &= 0x0000000Fu;
    *fm_loc |= f.block << 4;
    *fm_loc &= ~0x0000000Fu;                        /* andi.b #-0x10,(3,A2) */
    *fm_loc |= (uint32_t)(uint8_t)f.index;          /* or.b (-0x1b,A6) */

unlock:
    /* 0x00E39BAC-0x00E39BB2 */
    ML_$UNLOCK(VTOC_FM_LOCK);
}
